import { useMemo } from 'react';

import {
  Bar,
  BasicContainer,
  ChartLegend,
  ComparisonLine,
  DataStateHandler,
  Line,
  Skeleton,
} from 'components';
import { ChartLegendItem } from 'components/ChartLegend/ChartLegend';
import { PERFORMANCE_LINE_TOOLTIP_LABELS } from 'pages/pillars/ValueCreation/PerformanceTool/constants/performanceLineTooltipLabels';
import { LineBarChartsSectionData } from 'pages/pillars/ValueCreation/PerformanceTool/types';
import { getBarChartOptionsFromDatasets } from 'pages/pillars/ValueCreation/PerformanceTool/utils/getBarChartOptions';
import { theme } from 'theme';

import {
  StyledBodyContainer,
  StyledChartContainer,
  StyledChartsWrapper,
  StyledLegendContainer,
  StyledLineBarChartsGrid,
} from './LineBarChartsSection.styles';

interface LineBarChartsSectionProps {
  title: string;
  measure?: string;
  tooltip?: string;
  data?: LineBarChartsSectionData;
  loading: boolean;
  error?: Error | null;
  skeletonProps?: React.ComponentProps<typeof Skeleton>;
  showLineDataLabels?: boolean;
}

const CHART_COLORS = {
  lastYear: '#eddab1',
  budget: '#f1d715',
  current: '#d1a33c',
};

const getColor = (label?: string): string => {
  if (label === 'Last Year') return CHART_COLORS.lastYear;
  if (label === 'Budget') return CHART_COLORS.budget;
  return CHART_COLORS.current;
};

const getBarColors = (labels: string[], stripedIndexes: number[]) => {
  return labels.map((_, index, array) => {
    if (stripedIndexes.includes(index)) {
      return CHART_COLORS.budget;
    }

    if (index === array.length - 1) {
      return CHART_COLORS.current;
    }

    return CHART_COLORS.lastYear;
  });
};

export const LineBarChartsSection: React.FC<LineBarChartsSectionProps> = ({
  title,
  measure,
  tooltip,
  loading,
  error,
  data,
  skeletonProps = {
    height: '328px',
    width: '100%',
    length: 1,
    borderRadius: 'none',
  },
  showLineDataLabels = true,
}) => {
  const legendItems = useMemo<ChartLegendItem[]>(() => {
    if (!data?.legend) return [];

    return data.legend.map((item) => ({
      label: item.label,
      color: getColor(item.label),
      shape: 'rectangle',
      size: 'small',
      decoration: item.label === 'Budget' ? 'dash' : 'none',
    }));
  }, [data?.legend]);

  const lineDatasets = useMemo(() => {
    if (!data?.lineChart?.datasets) return [];
    return data.lineChart.datasets.map((dataset) => ({
      ...dataset,
      borderColor: dataset.borderColor || getColor(dataset.label),
      pointBackgroundColor:
        dataset.pointBackgroundColor || getColor(dataset.label),
    }));
  }, [data?.lineChart?.datasets]);

  const barDatasets = useMemo(() => {
    if (!data?.barChart?.datasets) return [];

    const labels = data.barChart.labels || [];
    const backgroundColors = getBarColors(
      labels,
      data?.barChart?.stripedIndexes || [],
    );

    return data.barChart.datasets.map((dataset) => ({
      ...dataset,
      backgroundColor: backgroundColors,
    }));
  }, [
    data?.barChart?.datasets,
    data?.barChart?.labels,
    data?.barChart?.stripedIndexes,
  ]);

  const highlightedIndexes = useMemo(() => {
    return data?.lineChart?.highlightedIndexes || [];
  }, [data?.lineChart?.highlightedIndexes]);

  const barOptions = useMemo(
    () => getBarChartOptionsFromDatasets(data?.barChart?.datasets),
    [data?.barChart?.datasets],
  );

  return (
    <BasicContainer
      header={{
        title,
        measure,
        tooltip,
        tooltipBackgroundTransparent: true,
        titleSize: 'H4',
      }}
      layout={{
        border: 'small',
        shadow: 'small',
        headerPadding: 'medium',
        bodyPadding: false,
        bottomSeparator: 'border',
      }}
    >
      <DataStateHandler
        loading={loading}
        error={error}
        empty={!data || !!data?.empty}
        skeletonProps={skeletonProps}
      >
        <StyledBodyContainer>
          <StyledLegendContainer>
            <ChartLegend items={legendItems} />
          </StyledLegendContainer>
          <StyledChartsWrapper>
            <StyledLineBarChartsGrid>
              <StyledChartContainer>
                <Line
                  datasets={lineDatasets}
                  labels={data?.lineChart?.labels}
                  formattedData={
                    showLineDataLabels
                      ? data?.lineChart?.formattedData
                      : undefined
                  }
                  labelColors={[
                    theme.colors.txt.secondary,
                    theme.colors.txt.default,
                  ]}
                  highlightedIndexes={highlightedIndexes}
                  options={{
                    layout: {
                      padding: {
                        top: 20,
                      },
                    },
                    scales: {
                      y: {
                        suggestedMin: data?.lineChart?.suggestedMin,
                        suggestedMax: data?.lineChart?.suggestedMax,
                        beginAtZero: false,
                        ticks: {
                          maxTicksLimit: 50,
                        },
                        afterFit: (axis) => {
                          axis.width = 45;
                        },
                      },
                    },
                  }}
                  showDivider
                  tooltip={{ tooltipLabels: PERFORMANCE_LINE_TOOLTIP_LABELS }}
                />
                {data?.lineChart?.comparisonLine && (
                  <ComparisonLine
                    data={data.lineChart.comparisonLine.data}
                    gridColumnsLength={data.lineChart.labels?.length || 0}
                    gridConfig={{ paddingLeft: 5, paddingRight: 0 }}
                    borderConfig={{ marginLeft: 40, marginRight: 8 }}
                  />
                )}
              </StyledChartContainer>
              <StyledChartContainer>
                <Bar
                  datasets={barDatasets}
                  labels={data?.barChart?.labels}
                  formattedData={data?.barChart?.formattedData}
                  stripedIndexes={data?.barChart?.stripedIndexes || []}
                  size="large"
                  showGrid={false}
                  showDivider={false}
                  axisType="none"
                  options={barOptions}
                />
                {data?.barChart?.comparisonLine && (
                  <ComparisonLine
                    data={data.barChart.comparisonLine.data}
                    gridColumnsLength={data.barChart.labels?.length || 0}
                    gridConfig={{ paddingLeft: 0, paddingRight: 0 }}
                    borderConfig={{ marginLeft: 16, marginRight: 16 }}
                  />
                )}
              </StyledChartContainer>
            </StyledLineBarChartsGrid>
          </StyledChartsWrapper>
        </StyledBodyContainer>
      </DataStateHandler>
    </BasicContainer>
  );
};
